package com.example.rokidgeminisecretary;
import android.content.*;import org.json.*;
public final class NavigationExperienceSettings {
 public static JSONObject read(Context c)throws Exception{android.content.SharedPreferences p=c.getSharedPreferences("loki_navigation_cues",0);return new JSONObject().put("walkingTiming",Math.max(0,Math.min(2,p.getInt("walkingTiming",1)))).put("bicycleTiming",Math.max(0,Math.min(2,p.getInt("bicycleTiming",1)))).put("adaptive",p.getBoolean("adaptive",true));}
 public static void set(Context c,String kind,int value)throws Exception{if(kind.equals("adaptive")){if(value<0||value>1)throw new Exception("表示設定を確認してください");c.getSharedPreferences("loki_navigation_cues",0).edit().putBoolean("adaptive",value==1).commit();return;}if(!kind.matches("walkingTiming|bicycleTiming")||value<0||value>2)throw new Exception("通知タイミングを確認してください");c.getSharedPreferences("loki_navigation_cues",0).edit().putInt(kind,value).commit();}
 static void show(android.app.Activity a){new android.app.AlertDialog.Builder(a).setTitle("通知タイミング・表示").setItems(new String[]{"徒歩の通知距離","自転車の通知距離","移動手段に合わせた表示"},(d,k)->{try{JSONObject state=read(a);if(k==2){new android.app.AlertDialog.Builder(a).setMessage("自転車は短い案内を大きく、公共交通は乗降と行き先を中心に表示します。既存の乗車・降車確認に従い、端末の動きだけで乗車扱いにしません。").setPositiveButton(state.optBoolean("adaptive")?"自動切り替えをオフ":"自動切り替えをオン",(x,w)->{try{set(a,"adaptive",state.optBoolean("adaptive")?0:1);}catch(Exception e){SavedNavigationRoutesDialog.error(a,e);}}).setNegativeButton("戻る",null).show();return;}String kind=k==0?"walkingTiming":"bicycleTiming";new android.app.AlertDialog.Builder(a).setTitle(k==0?"徒歩の通知距離（速度で変動）":"自転車の通知距離").setSingleChoiceItems(k==0?new String[]{"遅め：約80m以内","標準：約120m以内","早め：約180m以内"}:new String[]{"遅め：約150m以内","標準：約250m以内","早め：約400m以内"},state.optInt(kind,1),(x,w)->{try{set(a,kind,w);x.dismiss();}catch(Exception e){SavedNavigationRoutesDialog.error(a,e);}}).setNegativeButton("戻る",null).show();}catch(Exception e){SavedNavigationRoutesDialog.error(a,e);}}).setNegativeButton("閉じる",null).show();}
 private NavigationExperienceSettings(){}
}
